113.     private List<TaskItem> ApplySearch(List<TaskItem> tasks)
114.     {
115.         if (string.IsNullOrWhiteSpace(searchTerm))
116.             return tasks;
117. 
118.         return tasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();
119.     }
