121.     protected override async Task OnInitializedAsync()
122.     {
123.         try
124.         {
125.             allTasks = await TaskService.GetAllTasksAsync();
126.         }
127.         catch (Exception ex)
128.         {
129.             errorMessage = $"Failed to load tasks: {ex.Message}";
130.         }
131.         finally
132.         {
133.             isLoading = false;
134.         }
135.     }
