137.     private async Task MoveTask(int taskId, string newStatus)
138.     {
139.         try
140.         {
141.             await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
142.             var task = allTasks.First(t => t.Id == taskId);
143.             allTasks = allTasks.Select(t => t.Id == taskId ? t with { Status = newStatus } : t).ToList();
144.         }
145.         catch (Exception ex)
146.         {
147.             errorMessage = $"Failed to move task: {ex.Message}";
148.         }
149.     }
